46	export default function createGrid(
47	  options: {
48	    createStyledComponent?: typeof defaultCreateStyledComponent;
49	    useThemeProps?: typeof useThemePropsDefault;
50	    useTheme?: typeof useThemeSystem;
51	    componentName?: string;
52	  } = {},
53	) {
54	  const {
55	    // This will allow adding custom styled fn (for example for custom sx style function)
56	    createStyledComponent = defaultCreateStyledComponent,
57	    useThemeProps = useThemePropsDefault,
58	    useTheme = useThemeSystem,
59	    componentName = 'MuiGrid',
60	  } = options;
61	
62	  const useUtilityClasses = (ownerState: GridOwnerState, theme: typeof defaultTheme) => {
63	    const { container, direction, spacing, wrap, size } = ownerState;
64	    const slots = {
65	      root: [
66	        'root',
67	        container && 'container',
68	        wrap !== 'wrap' && `wrap-xs-${String(wrap)}`,
69	        ...generateDirectionClasses(direction),
70	        ...generateSizeClassNames(size),
71	        ...(container ? generateSpacingClassNames(spacing, theme.breakpoints.keys[0]) : []),
72	      ],
73	    };
74	
75	    return composeClasses(slots, (slot) => generateUtilityClass(componentName, slot), {});
76	  };
