78	  function parseResponsiveProp<T extends GridSize | GridOffset>(
79	    propValue: T | null | (T | null)[] | { [key in Breakpoint]?: T | null },
80	    breakpoints: Breakpoints,
81	    shouldUseValue: (val: T) => boolean = () => true,
82	  ): { [key in Breakpoint]: T } {
83	    const parsedProp = {} as { [key in Breakpoint]: T };
84	
85	    if (propValue === null) {
86	      return parsedProp;
87	    }
88	
89	    if (Array.isArray(propValue)) {
90	      propValue.forEach((value, index) => {
91	        if (value !== null && shouldUseValue(value) && breakpoints.keys[index]) {
92	          parsedProp[breakpoints.keys[index]] = value;
93	        }
94	      });
95	    } else if (typeof propValue === 'object') {
96	      Object.keys(propValue).forEach((key) => {
97	        const value = propValue[key as Breakpoint];
98	        if (value !== null && value !== undefined && shouldUseValue(value)) {
99	          parsedProp[key as Breakpoint] = value;
100	        }
101	      });
102	    } else {
103	      parsedProp[breakpoints.keys[0]] = propValue;
104	    }
105	
106	    return parsedProp;
107	  }
